import{_ as t,o as i,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const R=JSON.parse('{"title":"CDS Tentacle - RBD","description":"","frontmatter":{"title":"CDS Tentacle - RBD","date":"2024-08-23T00:00:00.000Z","updated":"2024-08-23T00:00:00.000Z","tags":["Ceph","RBD","分布式存储","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/CDS_Tentacle_-_RBD.md","filePath":"posts/2024/CDS_Tentacle_-_RBD.md","lastUpdated":1780459816000}'),s={name:"posts/2024/CDS_Tentacle_-_RBD.md"};function r(e,l,a,p,g,_){return i(),o("div",null,[...l[0]||(l[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： RBD (RADOS Block Device) 开发者峰会会议纪要</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： RBD 团队成员，Zia（负责一致性组快照镜像），Roma（负责快照调度器），niia 和 RAM（负责相关子任务）</p><p><strong>会议内容</strong>：</p><p><strong>一、一致性组快照镜像</strong></p><ul><li><strong>主要议题</strong>： 实现基于快照的一致性组镜像功能。</li><li><strong>关键细节</strong>： <ul><li>Zia 负责的主要 PR 目前功能基本就绪，但需完善处理一致性组强制提升、参数描述、同步元数据对象等细节。</li><li>Ramana 开发一致性组快照调度器，Nya 协助进行代码审查和快照列表功能开发。</li><li>重点关注强制提升的测试覆盖范围，需增加更复杂的测试用例，并考虑多快照测试。</li><li>快照调度器支持组级别快照调度，并应用于组内所有镜像，不支持不同镜像的不同调度策略。</li><li>将 PR 切分成多个部分，以降低风险并确保现有功能的稳定性。</li></ul></li></ul><p><strong>二、RBD 镜像相关缺陷</strong></p><ul><li><strong>主要议题</strong>： 解决 RBD 镜像功能中存在的缺陷。</li><li><strong>关键细节</strong>： <ul><li>解决克隆镜像中快照镜像功能的问题，确保克隆镜像可以正常进行快照镜像。</li><li>解决内置 LUKS 加密中数据损坏的问题，确保在快照镜像过程中数据一致性。</li><li>解决丢弃操作无法正确传播到二级集群的问题，确保二级镜像占用空间正确。</li><li>解决强制提升和源集群不可用问题，提高镜像功能的健壮性。</li></ul></li></ul><p><strong>三、内置 LUKS 加密和实时迁移改进</strong></p><ul><li><strong>主要议题</strong>： 改进内置 LUKS 加密功能和实时迁移功能。</li><li><strong>关键细节</strong>： <ul><li>解决从加密源读取数据时数据损坏的问题。</li><li>保留读取操作时的空间信息，确保加密镜像的碎片信息正确。</li><li>支持从其他子集群导入镜像，提高实时迁移的灵活性。</li><li>支持 NBD 格式实时迁移流，扩展实时迁移的适用场景。</li><li>解决从克隆镜像迁移时加密操作重复执行的问题。</li></ul></li></ul><p><strong>四、其他改进</strong></p><ul><li><strong>主要议题</strong>： 改进缺陷 API 和 libRADOS 库，使其支持非用户快照。</li><li><strong>关键细节</strong>： 确保非用户快照（如一致性组快照、镜像快照、垃圾箱快照）在 RBD 命令行工具中可访问，并修复仪表板中的相关问题。</li></ul><p><strong>五、后续行动计划</strong></p><ul><li>RBD 团队将继续推进 RBD 镜像功能、内置 LUKS 加密功能和实时迁移功能的改进，并修复相关缺陷。</li><li>将 PR 切分成多个部分，并逐步合并到 RBD 中。</li><li>与社区合作，解决其他改进项。</li></ul><p><strong>六、会议总结</strong></p><p>本次会议讨论了 RBD 镜像功能和实时迁移功能的改进计划，并明确了后续行动计划。RBD 团队将继续努力，提高 RBD 的功能和稳定性，为用户提供更好的存储解决方案。</p>',17)])])}const u=t(s,[["render",r]]);export{R as __pageData,u as default};
